mapper.select:

  AND l.expiry_date >= #{today}
  AND l.expiry_date <= #{horizon}
GROUP BY l.id, l.item_id, i.name, l.lot_number, l.expiry_date, u.name
HAVING COALESCE(SUM(sp.quantity), 0) > 0
ORDER BY l.expiry_date ASC, l.id ASC
LIMIT #{limit}


  AND l.expiry_date < #{today}
GROUP BY l.id, l.item_id, i.name, l.lot_number, l.expiry_date, u.name
HAVING COALESCE(SUM(sp.quantity), 0) > 0
ORDER BY l.expiry_date ASC, l.id ASC
LIMIT #{limit}

SELECT i.id AS item_id, i.name AS item_name, u.name AS unit_name, l.id AS lot_id, l.lot_number AS lot_number, sp.location_id AS location_id, sp.quantity AS quantity, l.expiry_date AS expiry_date FROM inventory_stock_position sp JOIN inventory_lot l ON l.id = sp.lot_id AND l.household_id = sp.household_id JOIN catalog_item i ON i.id = l.item_id AND i.household_id = sp.household_id JOIN catalog_unit u ON u.id = i.unit_id AND u.household_id = i.household_id WHERE sp.household_id = #{householdId} AND sp.quantity > 0 AND i.status = 'ACTIVE' AND sp.location_id IN
#{locationId}
AND i.name ILIKE CONCAT('%', #{itemNameContains}, '%')
ORDER BY i.name ASC, l.lot_number ASC, sp.location_id ASC, l.id ASC LIMIT #{limit}
